example:
service sweeper from cron {
    delivery { retries: 5 }   // ✗ a cron service consumes no queue
    on schedule("0 * * * *") () -> Effect[Result[(), String]] { … }
}

service outbox from queue("outbound-email") {
    delivery { retries: 5, deadLetter: "outbound-email-dlq" }   // ✓
    on message(message: String) -> Effect[QueueResult] by Producer { … }
}
